:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #20332c;
  background: #f2f5f1;
  font-size: 16px;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #e0ebe2 0, #f2f5f1 68%);
}
.card {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 44px);
  border: 1px solid #d9e3db;
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 20px 55px #234b3212;
}
.header { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 30px; }
.eyebrow { margin: 0 0 6px; color: #668174; font-size: .8rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.4rem); line-height: 1.15; letter-spacing: -.04em; }
.intro { margin: 9px 0 0; color: #66756d; }
button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 0 19px;
  border: 0;
  border-radius: 12px;
  background: #276348;
  color: #fff;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s, transform .15s, box-shadow .15s;
}
button:hover { background: #1e513a; box-shadow: 0 5px 14px #27634830; }
button:active { transform: translateY(1px) scale(.98); }
button:focus-visible, input:focus-visible { outline: 3px solid #d99544; outline-offset: 3px; }
.board {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 72px;
  grid-template-rows: auto 66px;
  gap: 10px;
}
.grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.grid input {
  width: 100%;
  min-width: 0;
  aspect-ratio: 1;
  padding: 0;
  border: 1px solid #dce6de;
  border-radius: 13px;
  background: #f4f7f4;
  color: #20332c;
  text-align: center;
  font: inherit;
  font-size: clamp(1.1rem, 5vw, 1.5rem);
  font-weight: 700;
  transition: background .15s, border-color .15s, box-shadow .15s;
  appearance: textfield;
  -moz-appearance: textfield;
}
.grid input::-webkit-inner-spin-button, .grid input::-webkit-outer-spin-button { margin: 0; -webkit-appearance: none; }
.grid input:hover { border-color: #9eb9a6; background: #edf4ef; }
.row-totals { display: grid; grid-template-rows: repeat(4, 1fr); gap: 8px; }
.column-totals { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.sum-cell, .corner-total {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border-radius: 12px;
  background: #edf3ee;
  color: #315d45;
  font-variant-numeric: tabular-nums;
  font-weight: 750;
}
.sum-cell { min-width: 0; font-size: 1.05rem; }
.sum-cell .sum-label, .corner-total .sum-label { color: #75857b; font-size: .7rem; font-weight: 650; }
.row-total { flex-direction: column; gap: 0; }
.row-total .sum-label { font-size: .65rem; }
.column-total { flex-direction: column; gap: 0; }
.corner-total { flex-direction: column; gap: 0; background: #e2eee5; }
.largest { border: 2px solid #d99544; background: #fff4df; color: #704a19; }
.hint { display: flex; align-items: center; gap: 9px; margin: 21px 0 0; color: #66756d; font-size: .9rem; }
.legend { width: 14px; height: 14px; border: 2px solid #d99544; border-radius: 4px; background: #fff4df; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 420px) {
  .header { align-items: flex-start; flex-direction: column; gap: 18px; }
  button { width: 100%; }
  .board { grid-template-columns: minmax(0, 1fr) 58px; gap: 7px; grid-template-rows: auto 58px; }
  .grid, .row-totals, .column-totals { gap: 6px; }
  .sum-cell { font-size: .95rem; }
}

const SIZE = 4;
const grid = document.querySelector('#grid');
const rowTotals = document.querySelector('#row-totals');
const columnTotals = document.querySelector('#column-totals');
const grandTotal = document.querySelector('#grand-total');
const status = document.querySelector('#status');
const cells = [];
const rowOutputs = [];
const columnOutputs = [];

function makeSum(label, className) {
  const element = document.createElement('div');
  element.className = `sum-cell ${className}`;
  element.setAttribute('aria-label', label);
  const caption = document.createElement('span');
  caption.className = 'sum-label';
  caption.textContent = label;
  const output = document.createElement('output');
  element.append(caption, output);
  return { element, output };
}

for (let row = 0; row < SIZE; row += 1) {
  cells[row] = [];
  for (let column = 0; column < SIZE; column += 1) {
    const input = document.createElement('input');
    input.type = 'number';
    input.min = '1';
    input.max = '9';
    input.step = '1';
    input.value = '1';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${column + 1}`);
    input.addEventListener('input', updateTotals);
    grid.append(input);
    cells[row][column] = input;
  }
  const sum = makeSum(`Row ${row + 1}`, 'row-total');
  rowTotals.append(sum.element);
  rowOutputs.push(sum);
}

for (let column = 0; column < SIZE; column += 1) {
  const sum = makeSum(`Column ${column + 1}`, 'column-total');
  columnTotals.append(sum.element);
  columnOutputs.push(sum);
}

function cellValue(input) {
  const value = Number(input.value);
  return Number.isFinite(value) ? value : 0;
}

function updateTotals() {
  const sums = cells.map((row) => row.reduce((total, input) => total + cellValue(input), 0));
  const largest = Math.max(...sums);
  rowOutputs.forEach((row, index) => {
    row.output.value = sums[index];
    row.element.classList.toggle('largest', sums[index] === largest);
  });
  columnOutputs.forEach((column, index) => {
    column.output.value = cells.reduce((total, row) => total + cellValue(row[index]), 0);
  });
  grandTotal.value = sums.reduce((total, sum) => total + sum, 0);
}

document.querySelector('#randomize').addEventListener('click', () => {
  cells.flat().forEach((input) => {
    input.value = String(Math.floor(Math.random() * 9) + 1);
  });
  updateTotals();
  status.textContent = 'Grid randomized. Totals updated.';
});

updateTotals();
